<?php
declare(strict_types=1);requireRole('admin');require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/activity.php';$activePage='contact-lens-orders';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired.';if(!$errors){try{if($action==='receive'){$power=filter_input(INPUT_POST,'power',FILTER_VALIDATE_FLOAT);$quantity=filter_input(INPUT_POST,'quantity',FILTER_VALIDATE_INT);$supplier=filter_input(INPUT_POST,'supplier_id',FILTER_VALIDATE_INT);$date=(string)($_POST['received_date']??'');if($power===false||!$quantity||$quantity<1||!$supplier||!DateTimeImmutable::createFromFormat('Y-m-d',$date))throw new RuntimeException('Enter valid stock receipt details.');$stmt=$db->prepare('INSERT INTO contact_lens_stock(power,quantity,supplier_id,last_received) VALUES(:power,:quantity,:supplier,:date) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity),supplier_id=VALUES(supplier_id),last_received=VALUES(last_received)');$stmt->execute(['power'=>number_format((float)$power,2,'.',''),'quantity'=>$quantity,'supplier'=>$supplier,'date'=>$date]);$message='Contact lens stock received.';$reference='LENS-STOCK';}else{$id=filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$reason=trim((string)($_POST['rejection_reason']??''));$current=filter_input(INPUT_POST,'current_power',FILTER_VALIDATE_FLOAT);if(!$id||!in_array($decision,['approve','reject','issue'],true))throw new RuntimeException('Invalid order action.');if($decision==='reject'&&$reason==='')throw new RuntimeException('A rejection reason is required.');$db->beginTransaction();$stmt=$db->prepare('SELECT * FROM contact_lens_orders WHERE id=:id FOR UPDATE');$stmt->execute(['id'=>$id]);$order=$stmt->fetch();if(!$order)throw new RuntimeException('Order was not found.');if(in_array($decision,['approve','reject'],true)&&$order['status']!=='pending')throw new RuntimeException('Order is no longer pending.');if($decision==='approve'){$power=$current===false?(float)$order['requested_power']:(float)$current;$stock=$db->prepare('SELECT quantity FROM contact_lens_stock WHERE power=:power FOR UPDATE');$stock->execute(['power'=>number_format($power,2,'.','')]);$available=(int)$stock->fetchColumn();$status=$available>0?'approved':'procurement-required';$db->prepare('UPDATE contact_lens_orders SET current_power=:power,status=:status,reviewed_by=:user,reviewed_at=NOW() WHERE id=:id')->execute(['power'=>number_format($power,2,'.',''),'status'=>$status,'user'=>$_SESSION['user_id'],'id'=>$id]);$message=$status==='approved'?'Order approved; matching power is in stock.':'Order approved but matching power requires procurement.';}elseif($decision==='reject'){$db->prepare("UPDATE contact_lens_orders SET status='rejected',rejection_reason=:reason,reviewed_by=:user,reviewed_at=NOW() WHERE id=:id")->execute(['reason'=>$reason,'user'=>$_SESSION['user_id'],'id'=>$id]);$message='Contact lens order rejected.';}else{if(!in_array($order['status'],['approved','procurement-required'],true))throw new RuntimeException('Order is not approved for issue.');$power=$order['current_power'];$stock=$db->prepare('SELECT quantity FROM contact_lens_stock WHERE power=:power FOR UPDATE');$stock->execute(['power'=>$power]);if((int)$stock->fetchColumn()<1)throw new RuntimeException('Requested lens power is out of stock.');$db->prepare('UPDATE contact_lens_stock SET quantity=quantity-1 WHERE power=:power')->execute(['power'=>$power]);$db->prepare("UPDATE contact_lens_orders SET status='issued',issued_by=:user,issued_at=NOW() WHERE id=:id")->execute(['user'=>$_SESSION['user_id'],'id'=>$id]);$message='Contact lens issued and power stock deducted.';}$db->commit();$reference='CL-'.str_pad((string)$id,4,'0',STR_PAD_LEFT);}logActivity('Contact Lenses',$message,$reference);$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=contact-lens-orders');exit;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to update contact lens workflow.';}}}
try{$stock=$db->query('SELECT ls.*,s.company_name FROM contact_lens_stock ls LEFT JOIN suppliers s ON s.id=ls.supplier_id ORDER BY ls.power')->fetchAll();$orders=$db->query('SELECT o.*,b.full_name,b.nic,ds.name division_name FROM contact_lens_orders o JOIN beneficiaries b ON b.id=o.beneficiary_id JOIN ds_divisions ds ON ds.id=b.ds_division_id ORDER BY CASE o.status WHEN "pending" THEN 0 WHEN "approved" THEN 1 WHEN "procurement-required" THEN 2 ELSE 3 END,o.id DESC')->fetchAll();$suppliers=$db->query("SELECT id,company_name FROM suppliers WHERE status='active' ORDER BY company_name")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$stock=$orders=$suppliers=[];$errors[]='Contact lens workflow is unavailable.';}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Contact Lens Orders | WIDMS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/admin-sidebar.php';?><div class="admin-shell"><header class="topbar"><div class="d-flex align-items-center gap-3"><button class="menu-button" id="menu-button">&#9776;</button><h1>Contact Lens Orders</h1></div></header><main class="dashboard-content admin-operation-page contact-lens-page"><?php if($success):?><div class="alert alert-success"><?=$success?></div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors),ENT_QUOTES,'UTF-8')?></div><?php endif;?><section class="admin-data-card"><div class="admin-data-header"><h2>Receive Contact Lens Stock by Power</h2></div><form method="post" class="master-inline-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="receive"><label>Power<input type="number" name="power" min="-30" max="30" step="0.25" required></label><label>Quantity<input type="number" name="quantity" min="1" required></label><label>Supplier<select name="supplier_id" required><option value="">Select supplier</option><?php foreach($suppliers as $s):?><option value="<?=(int)$s['id']?>"><?=htmlspecialchars($s['company_name'],ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></label><label>Received Date<input type="date" name="received_date" required></label><button class="admin-primary-action">Receive Stock</button></form><div class="admin-data-table-wrap"><table class="admin-data-table"><thead><tr><th>Power</th><th>In Stock</th><th>Company</th><th>Last Received</th><th>Status</th></tr></thead><tbody><?php if(!$stock):?><tr><td colspan="5" class="admin-empty-row">No contact lens stock available.</td></tr><?php else:foreach($stock as $r):?><tr><td><?=number_format((float)$r['power'],2)?></td><td><?=(int)$r['quantity']?></td><td><?=htmlspecialchars($r['company_name']?:'—',ENT_QUOTES,'UTF-8')?></td><td><?=$r['last_received']?:'—'?></td><td><?=$r['quantity']>0?'Available':'Out of Stock'?></td></tr><?php endforeach;endif;?></tbody></table></div></section><section class="admin-data-card operation-list-card"><div class="admin-data-header"><h2>All Contact Lens Orders</h2></div><div class="admin-data-table-wrap"><table class="admin-data-table lens-orders-table"><thead><tr><th>ID</th><th>Beneficiary</th><th>NIC</th><th>Division</th><th>Requested Power</th><th>Current Power</th><th>Status</th><th>Date</th><th>Action</th></tr></thead><tbody><?php if(!$orders):?><tr><td colspan="9" class="admin-empty-row">No contact lens orders available.</td></tr><?php else:foreach($orders as $r):?><tr><td>CL-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['nic'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['division_name'],ENT_QUOTES,'UTF-8')?></td><td><?=number_format((float)$r['requested_power'],2)?></td><td><?=$r['current_power']!==null?number_format((float)$r['current_power'],2):'—'?></td><td><?=ucwords(str_replace('-',' ',$r['status']))?></td><td><?=date('d M Y',strtotime($r['created_at']))?></td><td><?php if($r['status']==='pending'):?><form method="post" class="goods-decision-form"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="order"><input type="hidden" name="order_id" value="<?=(int)$r['id']?>"><input type="number" name="current_power" step="0.25" placeholder="Current power"><input name="rejection_reason" placeholder="Rejection reason"><button name="decision" value="approve" class="approve-button">Approve</button><button name="decision" value="reject" class="reject-button">Reject</button></form><?php elseif(in_array($r['status'],['approved','procurement-required'],true)):?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="action" value="order"><input type="hidden" name="order_id" value="<?=(int)$r['id']?>"><button name="decision" value="issue" class="approve-button">Issue from Stock</button></form><?php else:?><?=htmlspecialchars($r['rejection_reason']?:'—',ENT_QUOTES,'UTF-8')?><?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script></body></html>
